安全代码执行器。
用子进程执行 Z3 / Python 代码，防止 segfault 崩溃主进程。
"""

import io
import traceback
import multiprocessing
from dataclasses import dataclass, asdict
from typing import Optional

from config import EXEC_TIMEOUT


@dataclass
class ExecResult:
    output: str
    error: Optional[str]
    verdict: str              # "True" / "False" / "Unknown" / "Error"
    timed_out: bool

    def to_dict(self):
        return asdict(self)


def _parse_verdict(output: str) -> str:
    lines = [l.strip() for l in output.strip().splitlines() if l.strip()]
    if not lines:
        return "Error"

    last = lines[-1].lower()
    if last in ("true", "entailed"):
        return "True"
    if last in ("false", "contradicted"):
        return "False"
    if last in ("unknown", "neutral", "uncertain"):
        return "Unknown"
    return "Error"


def _run_in_child(code, result_queue):
    """Target function for child process."""
    import io
    from contextlib import redirect_stdout, redirect_stderr
    stdout_buf = io.StringIO()
    stderr_buf = io.StringIO()
    try:
        with redirect_stdout(stdout_buf), redirect_stderr(stderr_buf):
            exec(code, {"__builtins__": __builtins__})
        result_queue.put(("ok", stdout_buf.getvalue(), None))
    except Exception as e:
        result_queue.put(("error", stdout_buf.getvalue(), f"{type(e).__name__}: {e}\n{traceback.format_exc()}"))


def execute_code(code: str, timeout: int = EXEC_TIMEOUT) -> ExecResult:
    result_queue = multiprocessing.Queue()
    p = multiprocessing.Process(target=_run_in_child, args=(code, result_queue))
    p.start()
    p.join(timeout=timeout)

    if p.is_alive():
        p.kill()
        p.join(timeout=5)
        return ExecResult(output="", error="Execution timed out", verdict="Error", timed_out=True)

    if p.exitcode != 0:
        return ExecResult(
            output="",
            error=f"Child process crashed with exit code {p.exitcode} (likely segfault)",
            verdict="Error",
            timed_out=False,
        )

    try:
        status, output, error = result_queue.get_nowait()
    except Exception:
        return ExecResult(output="", error="No result from child process", verdict="Error", timed_out=False)

    if status == "ok":
        return ExecResult(output=output, error=None, verdict=_parse_verdict(output), timed_out=False)
    else:
        return ExecResult(output=output, error=error, verdict="Error", timed_out=False)
